INSERT INTO `sms_notifications` VALUES (1,'2026-07-22 11:54:11.635041','Twilio SMS failed: The number +91638300XXXX is unverified. Trial accounts cannot send messages to unverified numbers; verify +91638300XXXX at twilio.com/user/account/phone-numbers/verified, or purchase a Twilio number to send messages to unverified numbers','6383007210','Your ward Arun Kumar is absent from class on 20-07-2026.\nPlease contact the Class Coordinator immediately.\nStudents with low attendance may not be permitted to appear for semester examinations.','TWILIO','FAILED',35,NULL),(2,'2026-07-22 11:54:11.635041','Twilio SMS failed: The number +91638300XXXX is unverified. Trial accounts cannot send messages to unverified numbers; verify +91638300XXXX at twilio.com/user/account/phone-numbers/verified, or purchase a Twilio number to send messages to unverified numbers','6383007210','Your ward Ajay is absent from class on 20-07-2026.\nPlease contact the Class Coordinator immediately.\nStudents with low attendance may not be permitted to appear for semester examinations.','TWILIO','FAILED',75,NULL),(3,'2026-07-22 11:59:24.050786',NULL,'6383007210','Your ward Arun Kumar is absent from class on 20-07-2026.\nPlease contact the Class Coordinator immediately.\nStudents with low attendance may not be permitted to appear for semester examinations.','TWILIO','SUCCESS',35,'SM3b625b4e84fdde49efa986dfb20a5500'),(4,'2026-07-22 11:59:24.767893',NULL,'6383007210','Your ward Ajay is absent from class on 20-07-2026.\nPlease contact the Class Coordinator immediately.\nStudents with low attendance may not be permitted to appear for semester examinations.','TWILIO','SUCCESS',75,'SM7f031a14a08994fc378d6bf159fd3b40'),(5,'2026-07-22 12:54:02.195572',NULL,'6383007210','? Attendance Alert\n\nதங்களது மகள்/மகன் Arun Kumar தற்போது 20/07/2026 ஜெ.ஜெ பொறியியல் கல்லூரியின் வகுப்பறையில் இல்லை.\n\nஎனவே வகுப்பாசிரியருக்கு உடனே அழைக்கவும்.\n\nவருகைப் பதிவு குறையும் பட்சத்தில் பருவத் தேர்வுகள் எழுத இயலாது.\n\n----------------